// A physical printer this application knows about, as it last reported itself.
// Fields it has not reported are absent rather than guessed: a nozzle of zero
// would be a claim, and this is a record of what was heard.
struct PrinterDevice
{
    std::string id;
    std::string name;
    std::string model;
    std::string connection; // lan, cloud, or empty when it has not said
    // offline, idle, or printing -- what this application can observe, not a
    // claim about the machine.
    std::string activity{"offline"};
    std::optional<double>    nozzle_diameter;
    std::vector<std::string> materials;
    // Milliseconds since the epoch, absent when the device has never reported.
    std::optional<std::int64_t> observed_at_ms;
};

// One filament's share of a sliced plate.

virtual PresetListResult list_presets(const PresetQuery& query) const = 0;

// Every physical printer the application knows, reachable or not. A
// printer it has not heard from is a real answer to "what printers do I
// have", which is not the same question setup asks.
virtual std::vector<PrinterDevice> printers() const = 0;

std::vector<PrinterDevice> OrcaWorkspaceAdapter::printers() const
{
    wxASSERT(wxIsMainThread());
    std::vector<PrinterDevice> result;
    // The fork's own discovery, asked to include what it normally hides:
    // setup offers printers you can connect to now, but "what printers do I
    // have" is a different question and an unreachable one is a real answer.
    for (const PrinterSetup::DiscoveredPrinter& found : PrinterSetup::discover_printers(true)) {
        PrinterDevice device;
        device.id         = found.stable_id;
        device.name       = found.name;
        device.model      = found.device_model_id;
        device.connection = found.connection;
        device.activity   = found.activity == PrinterSetup::PrinterActivity::Printing ? "printing" :
                            found.activity == PrinterSetup::PrinterActivity::Idle     ? "idle" :
                                                                                        "offline";
        if (found.nozzle_diameter > 0.)
            device.nozzle_diameter = found.nozzle_diameter;
        if (found.observed_at_ms != 0)
            device.observed_at_ms = found.observed_at_ms;
        for (const auto& spool : found.spools)
            device.materials.push_back(spool.name);
        result.push_back(std::move(device));
    }
    return result;
}

