"""Evaluate JavaScript in JusPrin's Agent WebView over the Chrome DevTools Protocol.

Usage: python cdp.py "<expression>"      (the app must run with
REDACTED)
"""
import base64
import json
import os
import socket
import struct
import sys
import urllib.request
from urllib.parse import urlsplit

PORT = 9222


def agent_target():
    targets = json.load(urllib.request.urlopen("http://127.0.0.1:%d/json" % PORT, timeout=5))
    for target in targets:
        if target.get("type") == "page" and "agent" in target.get("url", "") and "index.html" in target.get("url", ""):
            return target
    raise SystemExit("No Agent page among: %s" % [t.get("url") for t in targets])


class Ws:
    def __init__(self, url):
        parts = urlsplit(url)
        self.sock = socket.create_connection((parts.hostname, parts.port), timeout=120)
        key = base64.b64encode(os.urandom(16)).decode()
        self.sock.sendall(("GET %s HTTP/1.1\r\nHost: %s:%d\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n"
                           "Sec-WebSocket-Key: %s\r\nSec-WebSocket-Version: 13\r\n\r\n"
                           % (parts.path, parts.hostname, parts.port, key)).encode())
        self.file = self.sock.makefile("rb")
        while self.file.readline() not in (b"\r\n", b""):
            pass

    def send(self, message):
        data = json.dumps(message).encode()
        mask = os.urandom(4)
        header = bytes([0x81])
        if len(data) < 126:
            header += bytes([0x80 | len(data)])
        elif len(data) < 65536:
            header += bytes([0x80 | 126]) + struct.pack(">H", len(data))
        else:
            header += bytes([0x80 | 127]) + struct.pack(">Q", len(data))
        self.sock.sendall(header + mask + bytes(b ^ mask[i % 4] for i, b in enumerate(data)))

    def recv(self):
        head = self.file.read(2)
        length = head[1] & 0x7F
        if length == 126:
            length = struct.unpack(">H", self.file.read(2))[0]
        elif length == 127:
            length = struct.unpack(">Q", self.file.read(8))[0]
        return json.loads(self.file.read(length))


def evaluate(expression):
    ws = Ws(agent_target()["webSocketDebuggerUrl"])
    ws.send({"id": 1, "method": "Runtime.evaluate",
             "params": {"expression": expression, "returnByValue": True, "awaitPromise": True}})
    while True:
        message = ws.recv()
        if message.get("id") == 1:
            result = message.get("result", {})
            if "exceptionDetails" in result:
                raise SystemExit("JS error: %s" % result["exceptionDetails"].get("text"))
            return result.get("result", {}).get("value")


if __name__ == "__main__":
    print(json.dumps(evaluate(sys.argv[1]), indent=1, ensure_ascii=False))

