import sys

pending = []


def edit(path, pairs):
    raw = open(path, encoding="utf-8", newline="").read()
    crlf = "\r\n" in raw
    text = raw.replace("\r\n", "\n")
    for old, new in pairs:
        if text.count(old) != 1:
            sys.exit("anchor %d times in %s: %r" % (text.count(old), path, old[:90]))
        text = text.replace(old, new, 1)
    pending.append((path, text.replace("\n", "\r\n") if crlf else text))


def create(path, text):
    pending.append((path, text))


