                                        {"backwardsEdges", mesh.backwards_edges}}},
                          {"unitsSuspicion", mesh.units_suspicion.empty() ? "none" : mesh.units_suspicion}};
    }
    if (analysis.features) {
        json faces = json::array(), holes = json::array();
