"""M3 unit 5: object_import, object_import_file, project_delete_items; retire import_model and inspect_selection."""
import sys

pending = {}


def load(path):
    if path in pending:
        return pending[path][1], pending[path][0]
    raw = open(path, encoding="utf-8", newline="").read()
    return raw.replace("\r\n", "\n"), "\r\n" in raw


def edit(path, pairs, every=False):
    text, crlf = load(path)
    for old, new in pairs:
        count = text.count(old)
        if count == 0 or (count != 1 and not every):
            sys.exit("anchor %d times in %s: %r" % (count, path, old[:90]))
        text = text.replace(old, new) if every else text.replace(old, new, 1)
    pending[path] = (crlf, text)


def cut(path, start_marker, end_marker, before_end=True):
    """Remove from start_marker up to (not including) end_marker."""
    text, crlf = load(path)
    start = text.index(start_marker)
    end = text.index(end_marker, start + len(start_marker))
    pending[path] = (crlf, text[:start] + text[end:])


