import sys
pending = {}


def load(path):
    if path in pending:
        return pending[path][1], pending[path][0]
    raw = open(path, encoding="utf-8", newline="").read()
    return raw.replace("\r\n", "\n"), "\r\n" in raw


def edit(path, pairs):
    text, crlf = load(path)
    for old, new in pairs:
        if text.count(old) != 1:
            sys.exit("anchor %d times in %s: %r" % (text.count(old), path, old[:90]))
        text = text.replace(old, new, 1)
    pending[path] = (crlf, text)


