def patch(p, pairs):
    raw = open(p, encoding="utf-8", newline="").read()
    crlf = "\r\n" in raw
    t = raw.replace("\r\n", "\n")
    for old, new in pairs:
        assert t.count(old) == 1, (p, old[:60])
        t = t.replace(old, new)
    open(p, "w", encoding="utf-8", newline="").write(t.replace("\n", "\r\n") if crlf else t)


